async function executeForwardMessages(global: GlobalState, sendParams: SendMessageParams, tabId: number) {
  const {
    fromChatId, messageIds, toChatId, withMyScore, noAuthors, noCaptions, toThreadId = MAIN_THREAD_ID,
  } = selectTabState(global, tabId).forwardMessages;
  const { messagePriceInStars, isSilent, scheduledAt, scheduleRepeatPeriod, effectId, attachments } = sendParams;
  const isForwardOnly = !sendParams.text && !sendParams.richMessage && !attachments?.length;
  const forwardEffectId = isForwardOnly ? effectId : undefined;

  const isCurrentUserPremium = selectIsCurrentUserPremium(global);
  const isToMainThread = toThreadId === MAIN_THREAD_ID;

  const fromChat = fromChatId ? selectChat(global, fromChatId) : undefined;
  const toChat = toChatId ? selectChat(global, toChatId) : undefined;

  const messages = fromChatId && messageIds
    ? messageIds
      .sort((a, b) => a - b)
      .map((id) => selectChatMessageOrEphemeral(global, fromChatId, id)).filter(Boolean)
    : undefined;

  if (!fromChat || !toChat || !messages || (toThreadId && !isToMainThread && !toChat.isForum)) {
    return undefined;
  }

  // R7: свой Telegram и прокси-чат — разные провайдеры; текст копируется сразу, файлы — через скачивание
  if (Boolean(fromChat.pxgProxy) !== Boolean(toChat.pxgProxy)) {
    const forwardable = messages.filter((message) => (
      !isServiceNotificationMessage(message) && selectCanForwardMessage(global, message)
    ));
    await copyAcrossProviders(global, {
      toChat, messages: forwardable, skipped: messages.length - forwardable.length,
      toThreadId, isSilent, scheduledAt, scheduleRepeatPeriod,
    }, tabId);
    return undefined;
  }

  const privateForwardName = selectUserFullInfo(global, fromChat.id)?.privateForwardName;
  const sendAs = selectSendAs(global, toChatId!);
  const draft = selectDraft(global, toChatId!, toThreadId || MAIN_THREAD_ID);
  const lastMessageId = selectChatLastMessageId(global, toChat.id);
  const localMessages: SendMessageParams[] = [];

  const [realMessages, serviceMessages] = partition(messages, (m) => !isServiceNotificationMessage(m));
  const forwardableRealMessages = realMessages.filter((message) => selectCanForwardMessage(global, message));
  const [ephemeralMessages, regularMessages] = partition(forwardableRealMessages, (message) => message.isEphemeral);
  for (const messagesToForward of [regularMessages, ephemeralMessages]) {
    if (!messagesToForward.length) continue;

    const messageSlices = global.config?.maxForwardedCount
      ? splitMessagesForForwarding(messagesToForward, global.config.maxForwardedCount)
      : [messagesToForward];
    for (const slice of messageSlices) {
      const forwardParams: ForwardMessagesParams = {
        fromChat,
        toChat,
        toThreadId,
        messages: slice,
        isSilent,
        scheduledAt,
        scheduleRepeatPeriod,
        sendAs,
        withMyScore,
        noAuthors,
        noCaptions,
        privateForwardName,
        isCurrentUserPremium,
        wasDrafted: Boolean(draft),
        lastMessageId,
        messagePriceInStars,
        effectId: forwardEffectId,
      };

      if (!messagePriceInStars) {
        callApi('forwardMessages', forwardParams);
      } else {
        const forwardedLocalMessagesSlice = await callApi('forwardMessagesLocal', forwardParams);
        localMessages.push({
          ...sendParams,
          forwardParams: { ...forwardParams, forwardedLocalMessagesSlice },
          forwardedLocalMessagesSlice,
        });
      }
    }
  }

  for (const message of serviceMessages) {
    const { text, entities } = message.content.text || {};
    const { sticker } = message.content;

    const replyInfo = selectMessageReplyInfo(global, toChat.id, toThreadId);

    const params: SendMessageParams = {
      chat: toChat,
      replyInfo,
      text,
      entities,
      sticker,
      isSilent,
      scheduledAt,
      scheduleRepeatPeriod,
      sendAs,
      lastMessageId,
    };

    await sendMessageOrReduceLocal(global, params, localMessages);
  }

  global = getGlobal();
  global = updateTabState(global, {
    forwardMessages: {},
    isShareMessageModalShown: false,
  }, tabId);
  setGlobal(global);
  return localMessages;
}

/** Своя сессия Telegram и прокси-чат — разные провайдеры: копия без автора, текст и файлы */
async function copyAcrossProviders(globalState: GlobalState, params: {
  toChat: ApiChat;
  messages: ApiMessage[];
  /** Сколько сообщений отсеяно ещё до копии: служебные и запрещённые к пересылке */
  skipped: number;
  toThreadId: ThreadId;
  isSilent?: boolean;
  scheduledAt?: number;
  scheduleRepeatPeriod?: number;
}, tabId: number) {
  const copies: Pick<SendMessageParams, 'text' | 'entities' | 'richMessage' | 'attachment' | 'groupedId'>[] = [];
  let skipped = params.skipped;
  const copyNotificationId = `pxg-copy-${Date.now()}`;
  const filesToCopy = params.messages.filter((message) => {
    const content = message.content;
    return !content.richMessage && hasNonTextContent(content)
      && Boolean(selectMessageDownloadableMedia(globalState, message));
  }).length;
  let lastCopyPercent = -1;
  const showCopyProgress = (percent: number) => {
    const rounded = Math.min(99, Math.max(0, Math.round(percent)));
    if (rounded === lastCopyPercent) return;
    lastCopyPercent = rounded;
    getActions().showNotification({
      message: { key: 'PxgCopyProgress', variables: { percent: rounded } },
      localId: copyNotificationId,
      tabId,
    });
  };
  if (filesToCopy > 0) showCopyProgress(0);
  let copiedFiles = 0;
  for (const message of params.messages) {
    const content = message.content;
    if (content.richMessage) {
      copies.push({ richMessage: content.richMessage });
      continue;
    }
    const caption = content.text ? stripCustomEmoji(content.text) : undefined;
    if (!hasNonTextContent(content)) {
      if (!caption?.text) {
        skipped++;
        continue;
      }
      copies.push({ text: caption.text, entities: caption.entities });
      continue;
    }

    // Файл скачиваем через провайдера источника и отправляем вложением в целевом чате
    const media = selectMessageDownloadableMedia(globalState, message);
    const url = media && getMediaHash(media, 'download');
    if (!media || !url) {
      skipped++;
      continue;
    }
    try {
      const downloaded = await callApi('downloadMedia', { url, mediaFormat: ApiMediaFormat.BlobUrl }, (progress) => {
        if (filesToCopy) showCopyProgress(((copiedFiles + progress) / filesToCopy) * 90);
      });
      const data = downloaded?.dataBlob;
      if (!data) {
        skipped++;
        copiedFiles++;
        continue;
      }
      const blob = typeof data === 'string' ? await (await fetch(data)).blob() : data;
      const attachment = await buildAttachment(getMediaFilename(media), blob);
      copies.push({ attachment, text: caption?.text, entities: caption?.entities, groupedId: message.groupedId });
      copiedFiles++;
      if (filesToCopy) showCopyProgress((copiedFiles / filesToCopy) * 90);
    } catch {
      skipped++;
      copiedFiles++;
    }
  }

  const standalone = copies.filter((copy) => !copy.groupedId);
  const albums = new Map<string, typeof copies>();
  for (const copy of copies) {
    if (!copy.groupedId) continue;
    const group = albums.get(copy.groupedId) || [];
    group.push(copy);
    albums.set(copy.groupedId, group);
  }

  const sendCopy = (copy: typeof copies[number], onProgress?: ApiOnProgress) => callApi('sendMessage', {
    chat: params.toChat,
    messageList: {
      chatId: params.toChat.id,
      threadId: params.toThreadId,
      type: params.scheduledAt ? 'scheduled' : 'thread',
    },
    ...copy,
    isSilent: params.isSilent,
    scheduledAt: params.scheduledAt,
    scheduleRepeatPeriod: params.scheduleRepeatPeriod,
  }, onProgress);

  let sentFiles = 0;
  const sendCopyWithProgress = async (copy: typeof copies[number]) => {
    if (!copy.attachment || !filesToCopy) {
      await sendCopy(copy);
      return;
    }
    await sendCopy(copy, (progress) => {
      showCopyProgress(90 + ((sentFiles + progress) / filesToCopy) * 9);
    });
    sentFiles++;
    showCopyProgress(90 + (sentFiles / filesToCopy) * 9);
  };

  try {
    for (const copy of standalone) await sendCopyWithProgress(copy);
    // Одна группа — один альбом: части должны стартовать вместе, иначе прокси отправит первую отдельно
    for (const group of albums.values()) {
      if (group.length === 1) {
        const [{ groupedId: _groupedId, ...single }] = group;
        await sendCopyWithProgress(single);
        continue;
      }
      await Promise.all(group.map(sendCopyWithProgress));
    }
  } finally {
    if (filesToCopy) getActions().dismissNotification({ localId: copyNotificationId, tabId });
  }

  if (skipped) {
    getActions().showNotification({
      message: { key: 'PxgCrossForwardSkipped', variables: { count: skipped } },
      tabId,
    });
  }

  let global = getGlobal();
  global = updateTabState(global, {
    forwardMessages: {},
    isShareMessageModalShown: false,
  }, tabId);
  setGlobal(global);
}

/** Медиа и прочее, что нельзя скопировать простым текстом между провайдерами */
function hasNonTextContent(content: ApiMessage['content']) {
  return Boolean(content.photo || content.video || content.audio || content.document || content.sticker
    || content.pollId || content.todo || content.contact || content.location
    || content.invoice || content.storyData || content.dice || content.giveaway || content.giveawayResults
    || content.paidMedia || content.action);
}

function cleanupExpiredMessagesForChat(
  actions: RequiredGlobalActions,
  chatId: string,
  messageIds?: number[],
) {
  const global = getGlobal();
  const byId = selectChatMessages(global, chatId);
  if (!byId) return;

  const serverTime = getServerTime();
  const messages = messageIds
    ? messageIds.map((id) => byId[id]).filter(Boolean)
    : Object.values(byId);

  const expiredIds: number[] = [];
  let closestExpiresAt: number | undefined;

  messages.forEach((message) => {
    if (!message.ttlPeriod) return;

    const expiresAt = message.date + message.ttlPeriod;
    if (expiresAt <= serverTime) {
      expiredIds.push(message.id);
    } else if (!closestExpiresAt || expiresAt < closestExpiresAt) {
      closestExpiresAt = expiresAt;
    }
  });

  if (expiredIds.length) {
    deleteMessages(global, chatId, expiredIds, actions);
  }

  const current = ttlCleanupTimersByChatId.get(chatId);

  if (messageIds) {
    // Incremental pass: only tighten the timer, the scheduled full pass covers the rest
    if (closestExpiresAt && (!current || closestExpiresAt < current.expiresAt)) {
      scheduleTtlCleanup(actions, chatId, closestExpiresAt, serverTime);
    }
    return;
  }

  if (current) {
    clearTimeout(current.timer);
    ttlCleanupTimersByChatId.delete(chatId);
  }

  if (closestExpiresAt === undefined) return;

  scheduleTtlCleanup(actions, chatId, closestExpiresAt, serverTime);
}

function scheduleTtlCleanup(
  actions: RequiredGlobalActions,
  chatId: string,
  expiresAt: number,
  serverTime: number,
) {
  const current = ttlCleanupTimersByChatId.get(chatId);
  if (current) {
    clearTimeout(current.timer);
  }

  const delay = Math.min(
    (expiresAt - serverTime) * SECOND_IN_MS + TTL_CLEANUP_DELAY_BUFFER,
    TTL_CLEANUP_MAX_DELAY,
  );
  const timer = window.setTimeout(() => {
    ttlCleanupTimersByChatId.delete(chatId);
    actions.cleanupExpiredTtlMessages({ chatId });
  }, delay);
  ttlCleanupTimersByChatId.set(chatId, { timer, expiresAt });
}

async function loadViewportMessages<T extends GlobalState>(
  global: T,
  chat: ApiChat,
  threadId: ThreadId,
  offsetId: number | undefined,
  direction: LoadMoreDirection,
  isOutlying = false,
  isBudgetPreload = false,
  onLoaded?: NoneToVoidFunction,
  ...[tabId = getCurrentTabId()]: TabArgs<T>
) {
  const chatId = chat.id;

  let addOffset: number | undefined;
  let sliceSize = MESSAGE_LIST_SLICE;
  switch (direction) {
    case LoadMoreDirection.Backwards:
      if (offsetId) {
        addOffset = -1;
        sliceSize += 1;
      } else {
        addOffset = undefined;
      }
      break;
    case LoadMoreDirection.Around:
      addOffset = -(Math.round(MESSAGE_LIST_SLICE / 2) + 1);
      break;
    case LoadMoreDirection.Forwards:
      addOffset = -(MESSAGE_LIST_SLICE + 1);
      if (offsetId) {
        sliceSize += 1;
      }
      break;
  }

  global = getGlobal();

  const currentUserId = global.currentUserId!;
  const isSavedDialog = getIsSavedDialog(chatId, threadId, currentUserId);
  const realChatId = isSavedDialog ? String(threadId) : chatId;

  const result = await callApi('fetchMessages', {
    chat: selectChat(global, realChatId)!,
    offsetId,
    addOffset,
    limit: sliceSize,
    threadId,
    isSavedDialog,
  });

  if (!result) {
    return;
  }

  const {
    messages, count, topics,
  } = result;

  global = getGlobal();

  const localTypingDrafts = selectThreadLocalStateParam(global, chatId, threadId, 'typingDraftIdByRandomId');
  const typingDraftMessages = localTypingDrafts ? Object.values(localTypingDrafts)
    .map((id) => selectChatMessage(global, chatId, id))
    .filter(Boolean) : [];
  const localMessages = chatId === SERVICE_NOTIFICATIONS_USER_ID
    ? global.serviceNotifications.filter(({ isDeleted }) => !isDeleted).map(({ message }) => message)
    : typingDraftMessages;
  const allMessages = ([] as ApiMessage[]).concat(messages, localMessages);
  const byId = buildCollectionByKey(allMessages, 'id');
  const ids = Object.keys(byId).map(Number);

  if (threadId !== MAIN_THREAD_ID && !getIsSavedDialog(chatId, threadId, global.currentUserId)) {
    const threadFirstMessageId = selectFirstMessageId(global, chatId, threadId);
    if ((!ids[0] || threadFirstMessageId === ids[0]) && threadFirstMessageId !== threadId) {
      const threadTopMessage = selectChatMessage(global, chatId, Number(threadId));
      const groupedIds = threadTopMessage?.groupedId
        ? selectMessageIdsByGroupId(global, chatId, threadTopMessage.groupedId)
        : undefined;

      if (groupedIds && groupedIds.length > 1) {
        ids.unshift(...groupedIds);
      } else {
        ids.unshift(Number(threadId));
      }
    }
  }

  global = addChatMessagesById(global, chatId, byId);
  global = isOutlying
    ? updateOutlyingLists(global, chatId, threadId, ids)
    : updateListedIds(global, chatId, threadId, ids);

  let listedIds = selectListedIds(global, chatId, threadId);
  const outlyingList = offsetId ? selectOutlyingListByMessageId(global, chatId, threadId, offsetId) : undefined;

  if (isOutlying && listedIds && outlyingList) {
    if (!outlyingList.length || areSortedArraysIntersecting(listedIds, outlyingList)) {
      global = updateListedIds(global, chatId, threadId, outlyingList);
      listedIds = selectListedIds(global, chatId, threadId);
      global = removeOutlyingList(global, chatId, threadId, outlyingList);
      isOutlying = false;
    }
  }

  if (!isBudgetPreload) {
    const historyIds = isOutlying && outlyingList ? outlyingList : listedIds;
    if (historyIds) {
      const { newViewportIds } = getViewportSlice(historyIds, offsetId, direction);
      global = safeReplaceViewportIds(global, chatId, threadId, newViewportIds, tabId);
    }
  }

  if (count !== undefined) {
    global = updateThreadInfoMessagesCount(global, chat.id, threadId, count);
  }

  topics.forEach((topicState) => {
    global = updateTopicWithState(global, chat.id, topicState);
  });

  setGlobal(global);
  onLoaded?.();

  getActions().cleanupExpiredTtlMessages({ chatId, messageIds: ids });
}

function findClosestIndex(sourceIds: number[], offsetId: number) {
  if (offsetId < sourceIds[0]) {
    return 0;
  }

  if (offsetId > sourceIds[sourceIds.length - 1]) {
    return sourceIds.length - 1;
  }

  return sourceIds.findIndex((id, i) => (
    id === offsetId
    || (id < offsetId && sourceIds[i + 1] > offsetId)
  ));
}

function getViewportSlice(
  sourceIds: number[],
  offsetId: number | undefined,
  direction: LoadMoreDirection,
) {
  const { length } = sourceIds;
  const index = offsetId ? findClosestIndex(sourceIds, offsetId) : -1;
  const isBackwards = direction === LoadMoreDirection.Backwards;
  const isAround = direction === LoadMoreDirection.Around;
  const indexForDirection = isBackwards ? index : (index + 1) || length;
  const sliceSize = isAround ? Math.round(MESSAGE_LIST_SLICE / 2) : MESSAGE_LIST_SLICE;
  const from = indexForDirection - sliceSize;
  const to = indexForDirection + sliceSize - 1;
  const newViewportIds = sourceIds.slice(Math.max(0, from), to + 1);

  let areSomeLocal;
  let areAllLocal;
  switch (direction) {
    case LoadMoreDirection.Backwards:
      areSomeLocal = indexForDirection >= 0;
      areAllLocal = from >= 0;
      break;
    case LoadMoreDirection.Forwards:
      areSomeLocal = indexForDirection < length;
      areAllLocal = to <= length - 1;
      break;
    case LoadMoreDirection.Around:
    default:
      areSomeLocal = newViewportIds.length > 0;
      areAllLocal = newViewportIds.length === MESSAGE_LIST_SLICE;
      break;
  }

  return { newViewportIds, areSomeLocal, areAllLocal };
}

export async function getPeerStarsForMessage<T extends GlobalState>(
  global: T,
  peerId: string,
): Promise<number | undefined> {
  const peer = selectPeer(global, peerId);
  if (!peer) return undefined;

  if (isApiPeerChat(peer)) {
    if (isChatAdmin(peer) || selectIsMonoforumAdmin(global, peerId)) {
      return undefined;
    }
    return peer.paidMessagesStars;
  }

  if (!peer?.paidMessagesStars) return undefined;

  const fullInfo = selectUserFullInfo(global, peer.id);
  if (fullInfo) {
    return fullInfo.paidMessagesStars;
  }

  const result = await callApi('fetchPaidMessagesStarsAmount', peer);
  return result;
}

async function sendMessageOrReduceLocal<T extends GlobalState>(
  global: T,
  sendParams: SendMessageParams,
  localMessages: SendMessageParams[],
) {
  if (!sendParams.messagePriceInStars) {
    sendMessage(global, sendParams);
  } else {
    const message = await callApi('sendMessageLocal', sendParams);
    if (message) {
      localMessages.push({
        ...sendParams,
        localMessage: message,
      });
    }
  }
}

async function sendMessage<T extends GlobalState>(global: T, params: SendMessageParams) {
  // @optimization
  if (params.replyInfo || IS_IOS) {
    await rafPromise();
  }

  await sendWithUploadProgress(global, Boolean(params.attachment), (progressCallback) => (
    callApi('sendMessage', params, progressCallback)
  ));
}

export async function sendEphemeralMessages<T extends GlobalState>(
  global: T,
  {
    chat,
    receiver,
    text,
    entities,
    richMessage,
    replyInfo,
    attachments,
    sticker,
    gif,
    topMsgId,
  }: SendEphemeralMessagesParams,
) {
  if (sticker || gif || !attachments?.length) {
    await callApi('sendEphemeralMessage', {
      chat,
      receiver,
      text,
      entities,
      richMessage,
      replyInfo,
      sticker,
      gif,
      topMsgId,
    });
    return;
  }

  for (const [attachmentIndex, attachment] of attachments.entries()) {
    const isFirst = attachmentIndex === 0;
    const result = await sendWithUploadProgress(global, true, (progressCallback) => (
      callApi('sendEphemeralMessage', {
        chat,
        receiver,
        text: isFirst ? text : undefined,
        entities: isFirst ? entities : undefined,
        richMessage: isFirst ? richMessage : undefined,
        replyInfo,
        attachment,
        topMsgId,
      }, progressCallback)
    ));
    if (!result) return;
  }
}

async function sendWithUploadProgress<T extends GlobalState, TResult>(
  global: T,
  hasAttachment: boolean,
  send: (progressCallback?: ApiOnProgress) => Promise<TResult>,
) {
  let currentMessageKey: MessageKey | undefined;
  const progressCallback: ApiOnProgress | undefined = hasAttachment ? (progress, messageKey: MessageKey) => {
    if (!uploadProgressCallbacks.has(messageKey)) {
      currentMessageKey = messageKey;
      uploadProgressCallbacks.set(messageKey, progressCallback!);
    }

    global = getGlobal();
    global = updateUploadByMessageKey(global, messageKey, progress);
    setGlobal(global);
  } : undefined;

  try {
    const result = await send(progressCallback);
    return result;
  } finally {
    if (progressCallback && currentMessageKey) {
      global = getGlobal();
      global = updateUploadByMessageKey(global, currentMessageKey, undefined);
      setGlobal(global);

      uploadProgressCallbacks.delete(currentMessageKey);
    }
  }
}

function cancelMessageUpload(message: ApiMessage) {
  const progressCallback = uploadProgressCallbacks.get(getMessageKey(message));
  if (progressCallback) cancelApiProgress(progressCallback);
}

async function sendMessagesWithNotification<T extends GlobalState>(
  global: T,
  sendParams: SendMessageParams[],
) {
  const chat = sendParams[0]?.chat;
  if (!chat || !sendParams.length) return;
  const starsForOneMessage = await getPeerStarsForMessage(global, chat.id);
  if (!starsForOneMessage) {
    getActions().sendMessages({ sendParams });
    return;
  }
  const messageIdsForUndo = sendParams.reduce((ids, params) => {
    if (params.localMessage?.id) {
      ids.push(params.localMessage.id);
    } else if (params.forwardedLocalMessagesSlice?.localMessages) {
      const forwardedIds = Object.values(params.forwardedLocalMessagesSlice.localMessages)
        .map((forwardedMessage) => forwardedMessage.id)
        .filter(Boolean);
      ids.push(...forwardedIds);
    }
    return ids;
  }, [] as number[]);

  const localForwards = sendParams[0]?.forwardedLocalMessagesSlice?.localMessages;
  const firstMessage = sendParams[0]?.localMessage
    || (localForwards && Object.values(localForwards)[0]);
  if (!firstMessage) return;

  const messagesCount = messageIdsForUndo.length;

  const firstSendParam = sendParams[0];
  let storySendMessage: RegularLangFnParameters | undefined;
  if (sendParams.length === 1 && firstSendParam.isStoryReply) {
    const { gif, sticker, isReaction } = firstSendParam;

    if (gif) {
      storySendMessage = { key: 'MessageSentPaidToastTitle', variables: { count: 1 }, options: { pluralValue: 1 } };
    } else if (sticker) {
      storySendMessage = { key: 'StoryTooltipStickerSent' };
    } else if (isReaction) {
      storySendMessage = { key: 'StoryTooltipReactionSent' };
    }
  }

  const titleKey: RegularLangFnParameters = storySendMessage || {
    key: 'MessageSentPaidToastTitle',
    variables: { count: messagesCount },
    options: { pluralValue: messagesCount },
  };

  getActions().sendMessages({ sendParams });

  getActions().showNotification({
    localId: getMessageKey(firstMessage),
    title: titleKey,
    message: {
      key: 'MessageSentPaidToastText',
      variables: { amount: formatStarsAsText(getTranslationFn(), starsForOneMessage * messagesCount) },
    },
    icon: 'star',
    shouldUseCustomIcon: true,
    type: 'paidMessage',
  });
}

